/** Self-contained local console. All user content is rendered with textContent. */
export function interactionPage(nonce:string){return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>记忆与表达 · iLink</title><style nonce="${nonce}">
:root{color-scheme:light dark;font-family:"Segoe UI","Microsoft YaHei",sans-serif;background:#101624;color:#e4eaf5}[hidden]{display:none!important}*{box-sizing:border-box}body{margin:0}main{max-width:1120px;margin:auto;padding:32px 22px 70px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:22px}h1{font-size:27px;margin:4px 0}h2{font-size:18px;margin:0 0 15px}.muted,small{color:#a3b1c8;font-size:13px;line-height:1.7}#identity{color:#91dac8}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{border:1px solid #334059;border-radius:16px;padding:24px;background:#192235}.wide{grid-column:1/-1}button{border:1px solid #5d8d91;border-radius:9px;background:#183b42;color:#d8fff4;padding:9px 15px;font:inherit;cursor:pointer}button:disabled{opacity:.45;cursor:wait}input,select,textarea{font:inherit;color:inherit;background:#101a2c;border:1px solid #455574;border-radius:7px;padding:6px}input[type=range]{padding:0;accent-color:#78d6c0;width:100%}input[type=checkbox]{accent-color:#78d6c0}.row{display:grid;grid-template-columns:80px 1fr 45px;gap:12px;align-items:center;margin:14px 0}.toggles{display:flex;gap:20px;flex-wrap:wrap;margin-bottom:20px}textarea{width:100%;min-height:90px;resize:vertical;line-height:1.7;margin:10px 0}.bar{height:8px;background:#0f1728;border-radius:10px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#65b6cd,#86dec2);border-radius:10px}.tag{display:inline-block;padding:3px 9px;background:#263c4c;color:#9ee2d3;border-radius:20px;font-size:12px;margin:0 5px 7px 0}.item{border-top:1px solid #334059;padding:13px 0;line-height:1.8;overflow-wrap:anywhere}.source{color:#a3b1c8;font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.7 inherit;margin:12px 0}#notice{position:sticky;top:0;z-index:2;background:#244844;border-radius:9px;padding:10px 16px;margin-bottom:18px;display:none}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:16px}.legend{font-size:12px;color:#a3b1c8}#login{display:none}#login input{width:100%;margin:14px 0}.empty{color:#a3b1c8;padding:15px 0}a{color:#9ee2d3}@media(max-width:740px){main{padding:22px 14px}.grid{grid-template-columns:1fr}.card{padding:19px}h1{font-size:23px}header{align-items:flex-start}.row{grid-template-columns:68px 1fr 40px}}
</style></head><body><main><div id="notice" role="status"></div><header><div><small>iLink · 本机控制台</small><h1>记忆与表达</h1><div id="identity">正在连接本通道…</div></div><button id="refresh">刷新状态</button></header>
<section class="card" id="login"><h2>打开本通道控制页</h2><p class="muted">在对应微信发送 memory panel，在本机浏览器打开返回的完整链接。每个链接只管理它所属的通道。</p><input id="access" type="password" autocomplete="off" placeholder="也可在此粘贴完整控制页链接"><button id="connect">连接</button></section>
<div class="grid" id="console" hidden>
<section class="card"><h2>回复风格</h2><div class="toggles"><label><input id="reply-enabled" type="checkbox"> 启用动态表达</label><label><input id="mood-enabled" type="checkbox"> 启用模拟情绪</label></div><div id="styles"></div><div class="row"><label for="verbosity">回复长度</label><select id="verbosity"><option value="inherit">继承人设</option value="concise">简洁</option><option value="normal">适中</option><option value="detailed">充分</option></select><span></span></div><p class="legend">有效强度为 0–5。继承时沿用当前会话的人设设置；保存只影响后续回合，不改写身份快照。</p><div class="actions"><button id="save">保存表达设置</button><span id="revision" class="muted"></span></div></section>
<section class="card"><h2>当前模拟情绪</h2><div id="mood-summary"></div><div id="mood-bars"></div><p class="muted">这些是表达状态，不是模型真实感受或用户性格。事件随时间恢复；任务结果、取消与权限保持准确。</p><div class="actions"><button id="reset">恢复情绪基线</button></div><div id="events"></div></section>
<section class="card"><h2>本轮用了哪些记忆</h2><div id="memories"></div><h2 style="margin-top:22px">召回排序</h2><div id="weights"></div><p class="muted">权重只排序合格来源。当前通道之外、已遗忘或不合格的内容不会因权重升高而进入候选。</p><button id="save-weights">保存召回权重</button></section>
<section class="card"><h2>本轮表达依据</h2><div id="last-plan"></div><h2 style="margin-top:22px">输入一句话，查看策略</h2><textarea id="query" maxlength="2000" placeholder="例如：你怎么看这个安排？"></textarea><button id="preview">预览表达策略</button><p class="muted">本地预览，不调用模型、不生成真实回复、不写入情绪事件。</p><div id="preview-result"></div></section>
</div></main><script nonce="${nonce}">
let token=new URLSearchParams(location.hash.slice(1)).get('token')||sessionStorage.getItem('ilink-panel-token')||'',state=null;if(token)sessionStorage.setItem('ilink-panel-token',token);history.replaceState(null,'',location.pathname);const $=id=>document.getElementById(id);const labels={warmth:'温暖甜度',humor:'幽默',tsundere:'傲娇',emoji:'表情',initiative:'主动追问',relevance:'相关性',time:'时间适用',explicit:'明确证据',calm:'平静',happy:'开心',curious:'好奇',concern:'关切',fatigue:'疲惫'};const scenes={chat:'日常交流',opinion:'意见交流',explain:'概念讲解',task:'操作或状态',direct:'直接结果'};const postures={plain:'平实清楚',considered:'保留判断',warm:'自然亲近',wry:'轻松机锋','playful-challenge':'善意挑衅','mock-reluctance':'俏皮嘴硬'};
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}function notice(t){$('notice').textContent=t;$('notice').style.display=t?'block':'none'}
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});const d=await r.json();if(!r.ok){if(r.status===401){$('login').style.display='block';$('console').hidden=true}throw Error(d.error||'请求失败')}return d}
function slider(host,key,value,inherit,base=2){const row=el('div',undefined,'row');row.append(el('label',labels[key]));const center=el('div');const range=el('input');range.type='range';range.min='0';range.max='5';range.step='1';range.value=value===null?String(base):String(value);range.id='range-'+key;const out=el('span',value===null?'继承 '+base:String(value));range.oninput=()=>out.textContent=range.value;center.append(range);if(inherit){const label=el('label',undefined,'legend'),cb=el('input');cb.type='checkbox';cb.checked=value===null;cb.id='inherit-'+key;range.disabled=cb.checked;cb.onchange=()=>{range.disabled=cb.checked;out.textContent=cb.checked?'继承 '+base:range.value};label.append(cb,document.createTextNode(' 继承人设'));center.append(label)}row.append(center,out);host.append(row)}
function planView(host,p){host.replaceChildren();if(!p){host.append(el('p','当前会话尚无表达回执。','empty'));return}host.append(el('span','场景提示：'+(scenes[p.scene]||p.scene),'tag'),el('span',p.delivery?(p.delivery.state==='accepted'?'约束已提交模型':'约束已准备，尚未确认接收'):'约束预览','tag'));for(const [k,v] of Object.entries(p.style))host.append(el('span',(labels[k]||'长度')+' '+(k==='verbosity'?({concise:'简洁',normal:'适中',detailed:'充分'}[v]||v):v),'tag'));if(p.expressionPolicy){host.append(el('div','允许姿态：'+p.expressionPolicy.postures.map(k=>postures[k]||k).join('、'),'muted'),el('div','表达约束 v'+p.expressionPolicy.version+'；模型依本会话语境选择，不代表已生成这些姿态。','source'))}for(const reason of p.reasons)host.append(el('div',reason,'muted'));host.append(el('div','身份版本 '+p.profileRevision+' · 表达配置版本 '+p.settingsRevision,'source'))}
function render(s){state=s;$('login').style.display='none';$('console').hidden=false;$('identity').textContent=s.identity.name+' · '+s.account+' · 身份 v'+s.identity.revision;$('revision').textContent='配置 v'+s.settings.revision;$('reply-enabled').checked=s.settings.reply.enabled;$('mood-enabled').checked=s.settings.mood.enabled;$('styles').replaceChildren();for(const key of ['warmth','humor','tsundere','emoji','initiative'])slider($('styles'),key,s.settings.reply[key],true,s.inheritedStyle[key]);$('verbosity').value=s.settings.reply.verbosity||'inherit';$('weights').replaceChildren();for(const key of ['relevance','time','explicit'])slider($('weights'),key,s.weights[key],false);
 $('mood-summary').replaceChildren(el('span',s.mood.enabled?'已开启':'已关闭','tag'),el('span',labels[s.mood.primary]||s.mood.primary,'tag'));for(const k of s.mood.mixed)$('mood-summary').append(el('span','掺着'+labels[k],'tag'));$('mood-bars').replaceChildren();for(const [k,v]of Object.entries(s.mood.values)){const row=el('div',undefined,'row'),bar=el('div',undefined,'bar'),fill=el('div',undefined,'fill');fill.style.width=v+'%';bar.append(fill);row.append(el('span',labels[k]),bar,el('span',String(v)));$('mood-bars').append(row)}$('events').replaceChildren();for(const event of s.mood.events.slice(0,3))$('events').append(el('div',new Date(event.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+' · '+event.signal,'source'));
 $('memories').replaceChildren();const memories=s.recall.selected||[];if(!memories.length)$('memories').append(el('p',s.recall.note||'本轮没有可展示的合格记忆。','empty'));for(const m of memories){const item=el('div',undefined,'item');item.append(el('div',m.content),el('div','来源会话 '+m.threadId+' · 消息 '+m.messageId,'source'),el('div',(m.reasons||[]).join(' · ')+' · 排序分 '+m.score,'source'));$('memories').append(item)}planView($('last-plan'),s.lastPlan)}
async function load(){try{render(await api('status'));notice('')}catch(e){notice(e.message)}}async function action(fn){for(const b of document.querySelectorAll('button'))b.disabled=true;try{await fn();notice('已完成')}catch(e){notice(e.message)}finally{for(const b of document.querySelectorAll('button'))b.disabled=false}}
$('refresh').onclick=load;$('connect').onclick=()=>{try{token=new URLSearchParams(new URL($('access').value).hash.slice(1)).get('token')||'';if(token)sessionStorage.setItem('ilink-panel-token',token);$('access').value='';load()}catch{notice('请粘贴完整控制页链接')}};
$('save').onclick=()=>action(async()=>{const reply={enabled:$('reply-enabled').checked,verbosity:$('verbosity').value==='inherit'?null:$('verbosity').value};for(const k of ['warmth','humor','tsundere','emoji','initiative'])reply[k]=$('inherit-'+k).checked?null:Number($('range-'+k).value);await api('settings',{revision:state.settings.revision,patch:{reply,mood:{enabled:$('mood-enabled').checked}}});render(await api('status'))});
$('reset').onclick=()=>action(async()=>{await api('mood/reset',{revision:state.settings.revision});render(await api('status'))});
$('save-weights').onclick=()=>action(async()=>{const weights={};for(const k of ['relevance','time','explicit'])weights[k]=Number($('range-'+k).value);await api('weights',{revision:state.weightsRevision,weights});render(await api('status'))});
$('preview').onclick=()=>action(async()=>{const r=await api('preview',{text:$('query').value});planView($('preview-result'),r.plan);$('preview-result').prepend(el('div',r.note,'muted'));if(r.memories.length)$('preview-result').append(el('div','将参考 '+r.memories.length+' 条本通道记忆','muted'))});
if(token)load();else{$('login').style.display='block';$('identity').textContent='等待本通道访问链接'}
</script></body></html>`;}
